                int g = sigs.FindIndex(r => r.Zip(s, (a, b) => Math.Abs(a - b) <= tol).All(x => x));
                if (g < 0)
                {
                    g = sigs.Count;
                    sigs.Add(s);
                    reps.Add(new GH_Panel(p));
                }
                groups.Add(g);
            }

            DA.SetDataList(0, groups);
            DA.SetData(1, sigs.Count);
            DA.SetDataList(2, reps);
        }
